// Check the shared token, then hand on a clean row.
//
// The token only keeps strangers out of the webhook. It does not prove the
// request came from a company phone, so everything below is treated as a
// CLAIM by the handset, not as fact.

const EXPECTED_TOKEN = 'PUT-YOUR-TOKEN-HERE';

const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const body = item.json.body || {};

  const supplied = headers['x-perimeter-token'];
  if (EXPECTED_TOKEN !== 'PUT-YOUR-TOKEN-HERE' && supplied !== EXPECTED_TOKEN) {
    throw new Error('Rejected: bad or missing x-perimeter-token header');
  }

  if (!body.row_key || !body.staff_id || !body.login_at) {
    throw new Error('Rejected: row_key, staff_id and login_at are all required');
  }

  // Server receipt time. The phone's clock is not authoritative.
  const receivedAt = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
  const claimed = Date.parse(body.logout_at || body.login_at);

  // Signed, in minutes: positive means the phone claims a time in the FUTURE.
  //
  // Only a future claim is evidence of a wound-forward clock. A row arriving
  // hours or days late is completely normal — that is the offline queue doing
  // its job after a weekend with no signal — so age alone must never be
  // treated as suspicious, or every delayed sync lands flagged and someone
  // has to defend their own timesheet.
  const driftMin = Number.isFinite(claimed)
    ? Math.round((claimed - Date.now()) / 60000)
    : null;

  let flag = body.flag || 'OK';
  if (!body.logout_at) flag = 'OPEN';
  else if (driftMin !== null && driftMin > 5) flag = 'CLOCK AHEAD';

  out.push({
    json: {
      row_key: body.row_key,
      staff_id: body.staff_id,
      name: body.name || '',
      date: body.date || '',
      login_at: body.login_at,
      logout_at: body.logout_at || '',
      duration_min: body.duration_min ?? '',
      duration_hhmm: body.duration_hhmm || '',
      site: body.site || '',
      ssid: body.ssid || '',
      bssid: body.bssid || '',
      bssid_match: body.bssid_match === true ? 'YES' : 'NO',
      lat: body.lat ?? '',
      lng: body.lng ?? '',
      accuracy_m: body.accuracy_m ?? '',
      method: body.method || 'AUTO',
      flag: flag,
      device_id: body.device_id || '',
      received_at: receivedAt,
      drift_min: driftMin ?? ''
    }
  });
}

return out;
